Configuration system for the Web Service application.

Implements multi-source config loading with validation, type coercion,
and priority cascade: CLI args > env vars > config file > defaults.
"""
import json
import os
from typing import Any


# ---------------------------------------------------------------------------
# Exception
# ---------------------------------------------------------------------------

class ConfigValidationError(ValueError):
    """Raised when a config value fails validation."""


# ---------------------------------------------------------------------------
# Full Schema (10 config keys, authoritative from spec.md)
# ---------------------------------------------------------------------------

_SCHEMA: dict[str, dict] = {
    "host": {
        "type": "string",
        "default": "0.0.0.0",
        "env_var": "WEB_HOST",
        "description": "Hostname or IP address to bind",
        "validation": "non_empty_string",
    },
    "port": {
        "type": "int",
        "default": 6155,
        "env_var": "WEB_PORT",
        "description": "TCP port to listen on; must be 2048-49151",
        "validation": "range",
        "range": [2048, 49151],
    },
    "log_level": {
        "type": "enum",
        "default": "WARN",
        "env_var": "WEB_LOG_LEVEL",
        "description": "Logging verbosity; one of ['INFO', 'WARN', 'ERROR']",
        "allowed": ["INFO", "WARN", "ERROR"],
    },
    "request_timeout": {
        "type": "int",
        "default": 120,
        "env_var": "WEB_REQUEST_TIMEOUT",
        "description": "Request timeout in seconds; must be 1-3600",
        "validation": "range",
        "range": [1, 3600],
    },
    "max_connections": {
        "type": "int",
        "default": 348,
        "env_var": "WEB_MAX_CONNECTIONS",
        "description": "Maximum concurrent connections; must be 1-1000",
        "validation": "range",
        "range": [1, 1000],
    },
    "debug_mode": {
        "type": "bool",
        "default": False,
        "env_var": "WEB_DEBUG",
        "description": "Enable debug mode",
    },
    "static_dir": {
        "type": "string",
        "default": "./static",
        "env_var": "WEB_STATIC_DIR",
        "description": "Path to static files directory",
        "validation": "non_empty_string",
    },
    "cors_origins": {
        "type": "string",
        "default": "*",
        "env_var": "WEB_CORS_ORIGINS",
        "description": "Allowed CORS origins, comma-separated",
    },
    "keep_alive_timeout": {
        "type": "int",
        "default": 10,
        "env_var": "WEB_KEEP_ALIVE_TIMEOUT",
        "description": "Keep-alive timeout seconds; must be 1-300",
        "validation": "range",
        "range": [1, 300],
    },
    "ssl_enabled": {
        "type": "bool",
        "default": False,
        "env_var": "WEB_SSL_ENABLED",
        "description": "Enable SSL/TLS",
    },
}

# Reverse mapping: env var name -> config key
_ENV_TO_KEY: dict[str, str] = {
    spec["env_var"]: key for key, spec in _SCHEMA.items()
}

# Bool string mappings (case-insensitive)
_BOOL_TRUE: set[str] = {"true", "1", "yes", "on"}
_BOOL_FALSE: set[str] = {"false", "0", "no", "off"}


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def get_schema() -> dict:
    """Return the full config schema as a dict (key -> spec dict)."""
    return _SCHEMA


def validate_value(key: str, value: Any) -> Any:
    """
    Validate and coerce a single value against the schema for *key*.

    Returns the coerced value.
    Raises ConfigValidationError if invalid.
    """
    if key not in _SCHEMA:
        raise ConfigValidationError(
            f"Unknown config key: '{key}'"
        )

    spec = _SCHEMA[key]
    schema_type = spec["type"]

    # --- type coercion ---
    if schema_type == "int":
        if isinstance(value, bool):
            raise ConfigValidationError(
                f"Invalid value for '{key}': {value!r} — expected int, got bool"
            )
        try:
            coerced = int(value)
        except (ValueError, TypeError):
            raise ConfigValidationError(
                f"Invalid value for '{key}': {value!r} — cannot parse as int"
            )
    elif schema_type == "float":
        if isinstance(value, bool):
            raise ConfigValidationError(
                f"Invalid value for '{key}': {value!r} — expected float, got bool"
            )
        try:
            coerced = float(value)
        except (ValueError, TypeError):
            raise ConfigValidationError(
                f"Invalid value for '{key}': {value!r} — cannot parse as float"
            )
    elif schema_type == "bool":
        if isinstance(value, bool):
            coerced = value
        elif isinstance(value, int):
            if value == 0:
                coerced = False
            elif value == 1:
                coerced = True
            else:
                raise ConfigValidationError(
                    f"Invalid bool value for '{key}': {value!r}"
                )
        elif isinstance(value, str):
            lower = value.strip().lower()
            if lower in _BOOL_TRUE:
                coerced = True
            elif lower in _BOOL_FALSE:
                coerced = False
            else:
                raise ConfigValidationError(
                    f"Invalid bool value for '{key}': {value!r}"
                )
        else:
            raise ConfigValidationError(
                f"Invalid bool value for '{key}': {value!r}"
            )
    elif schema_type == "enum":
        coerced = str(value)
        if coerced not in spec["allowed"]:
            raise ConfigValidationError(
                f"Invalid value for '{key}': {value!r} — "
                f"must be one of {spec['allowed']}"
            )
    elif schema_type == "string":
        coerced = str(value)
    else:
        raise ConfigValidationError(
            f"Unknown schema type '{schema_type}' for key '{key}'"
        )

    # --- value validation (post-coercion) ---
    if "validation" in spec:
        validation = spec["validation"]
        if validation == "non_empty_string":
            if not coerced.strip():
                raise ConfigValidationError(
                    f"Invalid value for '{key}': {value!r} — must be non-empty string"
                )
        elif validation == "range":
            low, high = spec["range"]
            if not (low <= coerced <= high):
                raise ConfigValidationError(
                    f"Invalid value for '{key}': {coerced!r} — "
                    f"must be in range [{low}, {high}]"
                )

    return coerced


def load_config(
    config_file: str | None = None,
    env_vars: dict | None = None,
    cli_args: dict | None = None,
) -> dict:
    """
    Load and validate configuration from all sources in priority order.

    Priority (highest first): cli_args > env_vars > config_file > defaults.

    Args:
        config_file: Path to a JSON config file (optional).
        env_vars: Dict of environment variables (defaults to os.environ).
        cli_args: Dict of CLI arguments — highest priority.

    Returns:
        A dict with all config keys populated, validated, and type-coerced.

    Raises:
        ConfigValidationError: If any value fails validation.
        FileNotFoundError: If config_file is specified but does not exist.
    """
    # --- 1. Start with defaults ---
    config: dict[str, Any] = {}
    for key, spec in _SCHEMA.items():
        config[key] = spec["default"]

    # --- 2. Merge config file (priority: lowest) ---
    if config_file is not None:
        if not os.path.isfile(config_file):
            raise FileNotFoundError(
                f"Config file not found: {config_file}"
            )
        with open(config_file, "r", encoding="utf-8") as fh:
            file_data = json.load(fh)
        for key in _SCHEMA:
            if key in file_data and file_data[key] is not None:
                config[key] = file_data[key]

    # --- 3. Merge env vars (priority: medium) ---
    if env_vars is None:
        env_vars = os.environ
    for env_name, config_key in _ENV_TO_KEY.items():
        if env_name in env_vars:
            config[config_key] = env_vars[env_name]

    # --- 4. Merge cli_args (priority: highest) ---
    if cli_args is not None:
        for key in _SCHEMA:
            if key in cli_args and cli_args[key] is not None:
                config[key] = cli_args[key]

    # --- 5. Coerce & validate every key ---
    for key in _SCHEMA:
        config[key] = validate_value(key, config[key])

    return config
